// `ios/` is generated by `expo prebuild` and gitignored, so the app's signing can't be edited in a
// checked-in Xcode project. This plugin points the app target's Release signing at build settings
// that xcodebuild can be given (NAME=value), which default to what the template has: automatic
// signing as Apple Development, which Xcode's own account handles on a Mac. A build on a machine
// with no Xcode account, like CI, names an installed profile instead.
//
//   SATTLE_CODE_SIGN_STYLE / SATTLE_CODE_SIGN_IDENTITY / SATTLE_PROVISIONING_PROFILE
//
// Only the app target reads them. Given as CODE_SIGN_STYLE and the rest, they would reach every
// CocoaPods target too, and a library given a provisioning profile fails the build.
const { IOSConfig, withXcodeProject } = require('expo/config-plugins');

const SETTINGS = {
  CODE_SIGN_STYLE: '"$(SATTLE_CODE_SIGN_STYLE:default=Automatic)"',
  CODE_SIGN_IDENTITY: '"$(SATTLE_CODE_SIGN_IDENTITY:default=Apple Development)"',
  PROVISIONING_PROFILE_SPECIFIER: '"$(SATTLE_PROVISIONING_PROFILE)"',
};

module.exports = function withIosReleaseSigning(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const { target } = IOSConfig.XcodeUtils.getApplicationNativeTarget({
      project,
      projectName: cfg.modRequest.projectName,
    });
    const release = IOSConfig.XcodeUtils.getBuildConfigurationsForListId(project, target.buildConfigurationList).filter(
      ([, buildConfig]) => buildConfig.name === 'Release',
    );
    if (!release.length) {
      // A silent miss would leave CI with nothing to sign by, so fail the prebuild.
      throw new Error('withIosReleaseSigning: the app target has no Release configuration');
    }
    for (const [, buildConfig] of release) Object.assign(buildConfig.buildSettings, SETTINGS);
    return cfg;
  });
};
